solutions.naive:
class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                seen = set()
                for k in range(i, j + 1):
                    seen.add(s[k])
                if len(seen) <= 2 and j - i + 1 > ans:
                    ans = j - i + 1
        return ans

