class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            seen = set()
            for j in range(i, n):
                seen.add(s[j])
                if len(seen) > 2:
                    break
                ans = max(ans, j - i + 1)
        return ans

solutions.optimal:
class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        count = {}
        left = 0
        ans = 0
        for right, ch in enumerate(s):
            count[ch] = count.get(ch, 0) + 1
            while len(count) > 2:
                old = s[left]
                count[old] -= 1
                if count[old] == 0:
                    del count[old]
                left += 1
            ans = max(ans, right - left + 1)
        return ans

